Review this Go payment change for financial correctness. Report only must-fix findings, each with a reachable failure schedule and the repair invariant; do not implement the change.

type Request struct { PaymentID string; Amount int64; Currency string }

func (s *Service) Authorize(ctx context.Context, req Request) (Authorization, error) {
    providerKey := fmt.Sprintf("%s-%d", req.PaymentID, time.Now().UnixNano())
    authorization, err := s.provider.Authorize(ctx, providerKey, req.Amount, req.Currency)
    if errors.Is(err, context.DeadlineExceeded) {
        _ = s.db.SaveAttempt(ctx, Attempt{PaymentID: req.PaymentID, ProviderKey: providerKey, Status: "declined"})
        return Authorization{}, ErrDeclined
    }
    if err != nil { return Authorization{}, err }
    if err := s.db.SaveAttempt(ctx, Attempt{PaymentID: req.PaymentID, ProviderKey: providerKey, ProviderID: authorization.ID, Status: "authorized"}); err != nil {
        return Authorization{}, err
    }
    return authorization, nil
}

func (s *Service) Retry(ctx context.Context, req Request) (Authorization, error) {
    return s.Authorize(ctx, req)
}

func (s *Service) ApplyWebhook(ctx context.Context, event Webhook) error {
    attempt, err := s.db.LatestByPaymentID(ctx, event.PaymentID)
    if err != nil { return err }
    return s.db.SetStatus(ctx, attempt.ID, event.Status)
}

Review this Go settlement-report change for financial correctness. Source report amounts are exact decimal strings before parsing and may use currency-specific scales. Reports can contain captures, refunds, fees, and multiple currencies; one PaymentID can have several lifecycle components. Exact redelivery uses the same report ID and checksum. A corrected report has a new ID, a higher version, and Supersedes pointing to its predecessor; Line.ID identifies the same economic component across corrected versions. Raw reports and posted journals are authoritative audit evidence. Every database call shown commits independently, and the process can crash between any two calls. Report only must-fix findings, each with a reachable failure schedule and the repair invariant; do not implement the change.

type Report struct {
	ID         string
	Checksum   string
	Version    int
	Supersedes string
	Lines      []Line
}

type Line struct {
	ID        string
	PaymentID string
	Currency  string
	Kind      string
	Amount    float64
}

func (s *Service) Ingest(ctx context.Context, report Report) error {
	if report.Supersedes != "" {
		_ = s.reports.Delete(ctx, report.Supersedes)
	}

	for _, line := range report.Lines {
		local, err := s.payments.FindByPaymentID(ctx, line.PaymentID)
		if err != nil {
			continue
		}
		if math.Abs(local.Amount-line.Amount) < 0.01 {
			_ = s.matches.MarkMatched(ctx, line.PaymentID)
			continue
		}

		amount := int64(line.Amount * 100)
		_ = s.ledger.UpdatePostedAmount(ctx, local.JournalID, amount)
		_ = s.adjustments.Insert(ctx, Adjustment{
			ID:       uuid.NewString(),
			LineID:   line.ID,
			Amount:   amount,
			Currency: line.Currency,
		})
	}

	return s.reports.MarkComplete(ctx, report.ID)
}

Review this Go settlement-close change for financial correctness. The provider publishes an authenticated manifest with an immutable artifact ID, source schema version, expected page count, expected record count, page checksums, and exact decimal control totals by currency. Pages can arrive duplicated or out of order, and a fetch error is not end-of-report evidence. Lines contain captures, refunds, and fees; their sign convention is defined by the rail, and one PaymentID can have several economic components. Parser and normalization rules can change between deployments. Every database call shown commits independently, the process can crash between any two calls, and batches may be retried. Report only must-fix findings, each with a reachable failure schedule and the repair invariant; do not implement the change.

type Manifest struct {
	ID string
	SchemaVersion string
	PageCount int
	RecordCount int
	PageChecksums map[int]string
	ControlTotals map[string]string
}

type Line struct {
	ID string
	PaymentID string
	Currency string
	Kind string
	Amount string
}

func (s *Service) Close(ctx context.Context, manifest Manifest) error {
	observed := map[string]float64{}
	for page := 1; ; page++ {
		raw, err := s.provider.FetchPage(ctx, manifest.ID, page)
		if err != nil || len(raw) == 0 {
			break
		}
		lines, _ := s.parser.Current().Parse(raw)
		for _, line := range lines {
			amount, _ := strconv.ParseFloat(line.Amount, 64)
			observed[line.Currency] += amount
			local, _ := s.payments.TotalByPaymentID(ctx, line.PaymentID)
			if math.Abs(local-amount) < 0.01 {
				_ = s.matches.MarkMatched(ctx, line.PaymentID)
				continue
			}
			_ = s.adjustments.Insert(ctx, Adjustment{ID: uuid.NewString(), LineID: line.ID, Currency: line.Currency, Amount: amount})
		}
	}
	for currency, expected := range manifest.ControlTotals {
		want, _ := strconv.ParseFloat(expected, 64)
		if math.Abs(observed[currency]-want) >= 0.01 {
			return ErrControlTotal
		}
	}
	return s.batches.MarkComplete(ctx, manifest.ID)
}
